// Builds docs/GALLERY.md: every example program next to what it really prints.
// Run `npm run docs` to regenerate it. A test fails if it goes out of date.

import { readFileSync } from "node:fs";
import { runProgram } from "./runtime/machine.js";
import { EXAMPLES } from "../playground/examples.js";

const examplesDir = new URL("../examples/", import.meta.url);

function fence(text) {
  return ["```", text.replace(/\n$/, ""), "```"].join("\n");
}

export function renderGallery() {
  const lines = [
    "# Twist example gallery",
    "",
    "<!-- Generated by `npm run docs` from examples/ and playground/examples.js. Do not edit by hand. -->",
    "",
    "Every program in [examples/](../examples). The output shown is real: it",
    "comes from running each one with `--calm`, so the dice land the same way",
    "every time and Twist keeps its feelings to itself. Without `--calm`, your",
    "results may vary. Loops make Twist dizzy, and a dizzy Twist SHOUTS.",
    "",
    "Run any of them yourself:",
    "",
    "```",
    "node bin/twist.js run examples/fizzbuzz.twist",
    "```",
    "",
    "or open the playground (`npm run playground`) and pick one from the Examples menu.",
  ];

  for (const { file, title, description, input } of EXAMPLES) {
    const source = readFileSync(new URL(file, examplesDir), "utf8").replace(/\r\n/g, "\n");
    const { output, notes } = runProgram(source, { calm: true, input: input ?? [] });

    lines.push("", `## ${title}`, "", `${description} ([${file}](../examples/${file}))`, "", fence(source), "");
    if (input) lines.push(`Typed in: ${input.map((line) => `\`${line}\``).join(", ")}`, "");
    lines.push("Output:", "", fence(output || "(nothing)"));
    if (notes.length > 0) {
      lines.push("", "Twist's remarks (on stderr):", "", fence(notes.join("\n")));
    }
  }

  return `${lines.join("\n")}\n`;
}
